FRONTEND = {'index.html': 'SOURCE_0', 'core.js': 'SOURCE_1', 'patterns.js': 'SOURCE_2', 'main.js': 'SOURCE_3', 'visuals.js': 'SOURCE_4', 'late.js': 'SOURCE_5', 'equipment.js': 'SOURCE_6', 'chromatic.js': 'SOURCE_7'}
FRONTEND = {name: globals()[variable] for name, variable in FRONTEND.items()}
BUILD_ID = hashlib.sha256(("".join(FRONTEND.values()) + MEDIA_ARCHIVE).encode()).hexdigest()[:16]
@st.cache_resource(show_spinner="게임 화면을 준비하고 있습니다…")
def prepare_frontend(build_id):
    directory = Path(tempfile.mkdtemp(prefix="flowery_code_" + build_id + "_"))
    with zipfile.ZipFile(io.BytesIO(base64.b85decode(MEDIA_ARCHIVE))) as assets:
        assets.extractall(directory)
    for name, source in FRONTEND.items():
        (directory / name).write_text(source, encoding="utf-8")
    return str(directory)
try:
    frontend_path = prepare_frontend(BUILD_ID)
except (OSError, ValueError, zipfile.BadZipFile) as exc:
    st.error(f"게임 화면 준비 실패: {exc}")
    st.stop()
flowery = components.declare_component("flowery_code_" + BUILD_ID, path=frontend_path)
flowery(key="flowery_code_" + BUILD_ID, default=None)
